SELECT 'batch_020_60f1e1a8_wav_16' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0796f5d3-fd3','sm-upload-0d698ddd-586','sm-upload-34a4e79c-3ac','sm-upload-3e4a3e0c-5e1','sm-upload-412884aa-3c6','sm-upload-5189133a-af2','sm-upload-55fa915d-2e6','sm-upload-642c5555-32e','sm-upload-68e21ac4-af0','sm-upload-962f69d3-a47','sm-upload-be4c6092-980','sm-upload-c823de32-b12','sm-upload-d38bae55-e32','sm-upload-d4898d69-3e7','sm-upload-d9e8676f-0f4','sm-upload-e258a0c1-196') AND album_id='al-379190d71773f7eda5c8e71260f1e1a8') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0796f5d3-fd3','sm-upload-0d698ddd-586','sm-upload-34a4e79c-3ac','sm-upload-3e4a3e0c-5e1','sm-upload-412884aa-3c6','sm-upload-5189133a-af2','sm-upload-55fa915d-2e6','sm-upload-642c5555-32e','sm-upload-68e21ac4-af0','sm-upload-962f69d3-a47','sm-upload-be4c6092-980','sm-upload-c823de32-b12','sm-upload-d38bae55-e32','sm-upload-d4898d69-3e7','sm-upload-d9e8676f-0f4','sm-upload-e258a0c1-196') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-379190d71773f7eda5c8e71260f1e1a8' AND name='cop十周年纪念专辑') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-379190d71773f7eda5c8e71260f1e1a8') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-379190d71773f7eda5c8e71260f1e1a8') AS calculated_size;
